CREATE TABLE "LinkedInAnalyticsSnapshot" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"socialAccountId" TEXT NOT NULL,"subjectType" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"targetId" TEXT,"reportDate" DATE NOT NULL,"startDate" DATE NOT NULL,"endDate" DATE NOT NULL,"metrics" JSONB NOT NULL,"rawResponse" JSONB NOT NULL,"fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LinkedInAnalyticsSnapshot_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "linkedin_analytics_subject_report_uq" ON "LinkedInAnalyticsSnapshot"("workspaceId","socialAccountId","subjectType","subjectId","reportDate");
CREATE INDEX "linkedin_analytics_workspace_date_idx" ON "LinkedInAnalyticsSnapshot"("workspaceId","reportDate");
CREATE INDEX "linkedin_analytics_account_type_fetched_idx" ON "LinkedInAnalyticsSnapshot"("workspaceId","socialAccountId","subjectType","fetchedAt");
CREATE INDEX "linkedin_analytics_target_idx" ON "LinkedInAnalyticsSnapshot"("targetId");
ALTER TABLE "LinkedInAnalyticsSnapshot" ADD CONSTRAINT "LinkedInAnalyticsSnapshot_workspaceId_socialAccountId_fkey" FOREIGN KEY ("workspaceId","socialAccountId") REFERENCES "SocialAccount"("workspaceId","id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LinkedInAnalyticsSnapshot" ADD CONSTRAINT "LinkedInAnalyticsSnapshot_targetId_fkey" FOREIGN KEY ("targetId") REFERENCES "SocialPostTarget"("id") ON DELETE CASCADE ON UPDATE CASCADE;
